BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (399::BIGINT, 'Este semestre los ejercicios de examen estuvieron un poco dificiles agregando que es un profe que califica binario, las tareas son entretenidas. A pesar de todo lo recomiendo mucho'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'be314d1f16e78742f25ce8419d64848fa21d451d0fa884cd7a8c7ae25fc1775f'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'En general bastante bien. Explica de buena forma y tampoco complica muchos los exámenes. El curso es interesante, pero sencillo. Son 5 exámenes cortos, usualmente pone cosas del libro/clase, pero califica algo rudo en ocasiones. Pero sí lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Muchos exámenes']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, '83964fc57f110a342388db95764ef265d6bccb6341608b044c12a17df6237222'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'Se pasa se si cumple con lo que pide. Es buena gente, un poco inflexible, clases un poco monótonas, pero se ve que sabe bastante.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2025-08-23T00:00:00+00:00'::TIMESTAMPTZ, 'd0798c5643290fe484d93c338524582a86a7faaf4bc97bf9f8a070f3e1d7228f'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'El curso con él es bastante sencillo. Si se estudia a conciencia se aprende. El profe es respetuoso en general.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos exámenes']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'ce81c64f9d54eeab85a42d05681277bf1ad1339b3da0f4b5f7c0cee8d03c77a2'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'Sinceramente, a como da el curso se pasa muy facil, da clases un poco aburridas y hace ejemplos de los temas, los quices los hace por temas, entonces es uno cada 2 semanas por ej. Simplemente es entregar las tareas que pide y saber lo que toca hacer en los quices y ya'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'dc127217ef62133148bd69a5af969a5716257fc0b542ed7f2e7f16253b0d8afb'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'Hace la clase super aburrida y no se aprende nada en esta electiva. Este semestre empezó a calificar mucho más duro que antes pero igualmente considero que si su único interés es pasar una electiva esta es la opción más fácil'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '1bfa9b7499c621ceb0c28162d180f17803d9e9430cf31f030d0e86b8e12aebba'::TEXT, ARRAY[1347]::BIGINT[]),
    (399::BIGINT, 'Su calificación es totalmente binaria y la organización de su curso es bastante pobre. Es mejor llevar el curso con otro profesor porque su clase está basada en quices y no se aprende nada realmente importante.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2024-05-27T00:00:00+00:00'::TIMESTAMPTZ, '0e5a04c4ade5f1c5cc9981c0062e09a3678ece75fd5e44e5d8a0f23bec15e3ad'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'Modalidad mitad virtual mitad presencial, en las virtuales vemos materia y en la presencial se hacen quices bastante realizables. El profe explica lo necesario y no hace el curso difícil, pero su metodología si sirve para aprender lo justo Las tareas son medio cortas, solo tiene que sacar el rato.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Aspectos de calificación claros']::TEXT[], '2023-11-26T00:00:00+00:00'::TIMESTAMPTZ, '26cf6d7dd9d616c190c4cbf288ee21cf896025ff11b614497f8268ea44997d64'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'Es el taller electivo más sencillo, se trabaja con puros sensores en Labview. Los labs son chivas pero obvio hay que dedicarle tiempo.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4dbb5ea161cccf46a72c32d03570c9d9c06c739a78a670add9329a9bf7e4a9ed'::TEXT, ARRAY[1355]::BIGINT[]),
    (399::BIGINT, 'Los laboratorios son una agonía, los proyectos son interesantes, preparen todas las preguntas que puedan en la primera entrega porque después muere el asunto, lleven las varas armadas y probadas, sino les toca freestyle en clase.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '6f016e4d069964ffc1b86b57c2d9544125790db728f06f1bdf1c8a7e08e47a9c'::TEXT, ARRAY[1299]::BIGINT[]),
    (399::BIGINT, 'Es muy buena gente, es fácil y divertido'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-18T00:00:00+00:00'::TIMESTAMPTZ, '591eac2b5e96edcfdb588a05eb93b4db548a70fe4f1443eb597985eb8d138680'::TEXT, ARRAY[1347]::BIGINT[]),
    (399::BIGINT, 'Le da pereza su trabajo y hace todo por salir del paso. Revisa con pereza y muy por encima los examenes asi que siempre vaya a recoger su examen y reviselo bien porque califica de manera que a nadie le de para repo ya que (nuevamente) le da pereza hacerla.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-09T00:00:00+00:00'::TIMESTAMPTZ, '46e584f6ad1c135ef20738b0bbb1f0e85c07be8e0de68d31c0d39c7d5d9a0065'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'Las practicas para el examen no son para nada a lo que pide en el examen, y espera que con ejercicios super fáciles los estudiantes se preparen para los exámenes'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'efff4b37916dfc1bc1443ff7a7f7e77ab8dd66c96594c22a00bdc206b81a5ced'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'Pésimo, es un sin verguenza. Tras de que las "clases" eran videos de el leyendo presentaciones de power point, los ejemplos no se parecen en nada a los examenes. Califica como si explicara algo y es un agarrado. Cero recomendado, quedó a todo mundo el sin verguenza.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'dfcb198f96b515fc38eb88bc41bdaffe78acbb269281d2d9114b291e576aef9b'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'Pésimo profesor. Una clase que se supone debe ser de casi 4 horas, la da en 30 - 60 minutos, solo pone vídeos de semestres anteriores. Califica suave las tareas pero los examenes los califica MUY duro y hay que ser muy autodidacta. No lo recomiendo para nada.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'cf79a409303bcc8af138a857f641090263a5f6f2919114cc985e8208289c64df'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'Para ser virtual las clases está bien organizadas, pero casi todo son videos grabados. Califica duro y las tareas son muy largas quitan mucho tiempo. Ahora los exámenes son presenciales y es más difícil. El mae es estricto pero imparcial.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-05-21T00:00:00+00:00'::TIMESTAMPTZ, 'e5af4514389693f710ad5dc5a47b3824d92b8f738a6e1cb84b6510da8352c74e'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'Solo repite videos que ya tiene grabados, completamente mecánico, cero flexibilidad, trata de terminar lo mas rápido que puede la clase, los parciales son 20 preguntas y 40 minutos para resolver, lo que no da tiempo de contestar todo, se pierden no por difíciles, sino por la metodología.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-01T00:00:00+00:00'::TIMESTAMPTZ, '3098747372f670afff5d0aa280a3376624367d9dab988ea4bb310d80dfe2e1b3'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'Las clases son conectarse a ver la grabacion de semestres pasados, repite los mismos labs, ejercicios y quices, solo cambia el proyecto. No se aprende pero se pasa. No contesta correos'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2021-12-27T00:00:00+00:00'::TIMESTAMPTZ, '03c033c70fdf22147aca826d8c0d9be3f6931a7ee2a5b09044ed14e4203a667d'::TEXT, ARRAY[1355]::BIGINT[]),
    (399::BIGINT, 'Muy desordenado, solamente da menos de una hora por semana de clases. Pone un vídeo para escucharlo, deje mucho que desear la forma en que califica, al parecer quita puntos al estudiante como sea. NO RECOMENDADO'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'f0dab54648bdfc2f1627c74686b0043249e6ee953e1bffe9f866a7ebfe4f780f'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'El curso es fácil por dicha, pero busca quitar puntos por todo. Además no enseña nada, la verdad deja debiendo bastante'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'cf57766b14fc3fad078633ab9c79005fc41c63d40249d557a712854a5e89049f'::TEXT, ARRAY[1299]::BIGINT[]),
    (399::BIGINT, 'Existencia de programa computacional para la trazabilidad de la información en donde se califica al empleado público y, se genere un registro histórico y público para dar seguimiento a los empleados y la calidad de servicio que brindan. Así, puede ser evaluado por profesionales jurídicos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-07-11T00:00:00+00:00'::TIMESTAMPTZ, '0c56fd0f0e43ce87fc69202fa05d07dc8871a4c3ed839edf4cd4fe1694e677fa'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'El curso es prácticamente el libro de multisim y uno que otro trabajo pero al final no es complicado. El problema recae si tienes dificultades en la presentación del proyecto al ser para nada flexible a la hora de presentarlo y tener inconvenientes posibles en el ambito virtual.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-08T00:00:00+00:00'::TIMESTAMPTZ, 'a711cbffcb70ba9769d0e5cb7d52a4c98ce29eac76700673d3e2fca7185b7cc3'::TEXT, ARRAY[1299]::BIGINT[]),
    (399::BIGINT, 'Es un buen profe, cualquier duda puede preguntar por correo, no responde los fin de semana. Los quizes son matados, pero el resto de evaluación es bastante llevadera. El curso es interesante e incluso más fácil que Instru 1.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-16T00:00:00+00:00'::TIMESTAMPTZ, '20b826f1acbbc1a788a1b0027824494e245eb0029fbfc888e3677f84b52dfa8f'::TEXT, ARRAY[1355]::BIGINT[]),
    (399::BIGINT, 'Da una clase sincrónica en la que pone un video de él explicando un poco la materia. La clase asincrónica deja una tarea de resolver ejercicios del libro. Básicamente, el libro es el curso y ya con eso se pasa. La metodología de los exámenes es mala, 20 preguntas de marque con x con 40 min.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '65171c7b84cf1000864b8a4a6631cc6d3222fcc3627d86945a1dc36fc979eb0f'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'Este es el taller fácil de las electivas de electro. Matricúlelo y ya pasó. Se lee mucho por unos quices que hace y las clases no sirven de nada (el profe pone un video de él hablando o videos de otra gente). El proyecto final es en LabVIEW y es un chiste (lástima porque pichudo LabVIEW)'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Requiere mucha lectura']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '698fe4ae94fd052a5b41e9b49b2d4502d2085fe8c82de030a6523bd19fce1607'::TEXT, ARRAY[1355]::BIGINT[]),
    (399::BIGINT, 'El curso de manera virtual es una broma, pero es una lástima que uno no aprende nada. Espero que en el futuro lo cambien, pues en el curso literalmente no se aprende nada nuevo. Tengo entendido que de manera presencial es casi lo mismo. Una lástima'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'bfa1281a2df6f81c2d27f47bee84f5a0d5b478b6e0ee093ebb6402c358ccffc2'::TEXT, ARRAY[1355]::BIGINT[]),
    (399::BIGINT, 'El profesor no explicaba nada, todo lo mandaba en inglés, proyectos difíciles y vea a ver cómo se la juega. El curso se pasa fácil pero los proyectos y quices fueron sufridos. Presencialmente lo único que hacía era poner videos de otra gente explicando. Literal se fue de vacaciones todo el semestre.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '3be46282d0f917e2ba52ee1eb5815771aaea706c9bc26ca54d682033c31073d9'::TEXT, ARRAY[1355]::BIGINT[]),
    (399::BIGINT, 'Exámenes de muy pocos puntos. El curso se pasa fácil y no demanda mucho tiempo. La mayoría de clases son asincrónicas y el profe da una guía de trabajo para cada semana. Recomendado para este curso.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '6c743337f1cb1fd64514f5f0030ac6e1943cf16f14f8c9f4b4c3cd0a1c942915'::TEXT, ARRAY[1288]::BIGINT[]),
    (399::BIGINT, 'No entiendo cuál es el afán de desaparecer en los cursos que da. En este subió semanalmente lo que teníamos que hacer sin siquiera dar la materia. Aparte que rebaja puntos por "entrega tardía" cuando no había fecha límite de entrega. Parece que se la tiró de vacaciones durante todo el semestre.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '57a3dac285dfd8e6f6935b103780620b4b5f1443868b510f4ee9a2bd007d8b9e'::TEXT, ARRAY[3559]::BIGINT[]),
    (399::BIGINT, 'Como llegó a ser director de carrera? No lo sé. Es desorganizado y a a veces no maneja bien la materia, por dicha la mayor parte del trabajo es de uno y no tanto que el enseñe. Cuesta montones que responda un correo, incluso en cuarentena y en horas de clase. No da retroalimentación de los avances.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '7c5ee0f4677e95a1f2b643a874bd12fe77b0e1d5fbf922f11a2c526ef5fbdadb'::TEXT, ARRAY[3559]::BIGINT[]),
    (399::BIGINT, 'El profesor desapareció una vez que empezó la cuarentena. Cuando eran presenciales lo único que hacíamos era ver un video de cinco minutos y nos tiraba a nuestra suerte a hacer práctica. Proyectos dificiles, ya que nadie tiene idea de que está pidiendo porque la clase no existe.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'fe05cf5c0018f2e4389a826bbd597997d3d01efe5fdbc9eeef4bfb58727c6f4a'::TEXT, ARRAY[1355]::BIGINT[]),
    (399::BIGINT, 'Everything is in english'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, 'db5a83c26d931575bf5d042615b579ee42220a4fd2b1a00c934579fd10a3df8b'::TEXT, ARRAY[1355]::BIGINT[]),
    (399::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '3a27f32cc95eecb56ccbc5b99f1b8a8653d7ccc17abd63b7a1de50eec714c483'::TEXT, ARRAY[1355]::BIGINT[]),
    (399::BIGINT, 'El curso es regalado, el mae explica bien. No sirve de nada preguntar en clase porque se ataranta y empieza a responder todo buena gente cosas que nadie preguntó jajaj se aprende Minitab en el curso'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'debad697cc0dc452da1878a0aa80a8650649fbe472bca2a246150c148697da1e'::TEXT, ARRAY[1274]::BIGINT[]),
    (399::BIGINT, 'El curso está basado en unos instructivos de National Instruments. El profesor no se sabe ni las prácticas, nunca entiende las dudas ni las aclara bien pero si califica los informes como si hubiera explicado bien.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2020-01-29T00:00:00+00:00'::TIMESTAMPTZ, '2116c4699cfc1b64ca91fa121152cbbed9f3480a34641abf1b792fd13c60a303'::TEXT, ARRAY[1355]::BIGINT[]),
    (399::BIGINT, 'Siento que no aprendí nada en este curso, en especial porque las prácticas estaban mal diseñadas y porque el profesor no demostraba interés en la clase. Si bien es muy fácil pasar con buena nota,siento que este señor no sabía lo que estaba enseñando.Se desaparecía del lab y casi no ayudaba.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-07T00:00:00+00:00'::TIMESTAMPTZ, '7a58ca8002aa17ac6b14e0c6e51b7287ad0bf052b81e593f4ca70bbca87488d1'::TEXT, ARRAY[1355]::BIGINT[]),
    (399::BIGINT, 'Van a estar trabajando todas las semanas en los proyectos, no es muy bueno para despejar dudas, y aveces califica duro , es una buena opción, recomiendo elegir bien al equipo de trabajo(todo es grupal)'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-11-29T00:00:00+00:00'::TIMESTAMPTZ, '13b1f72a09bae934f54ed95f596feb3cc83389cbe121ed12165f82251c630860'::TEXT, ARRAY[1299]::BIGINT[]),
    (399::BIGINT, 'El profesor se encuentra fuera de contexto con la materia, y el curso no superó las expectativas. Calificaba duro los informes y se basaba en un solucionario erróneo para calificar muchos de ellos. Se escondía cuando alguien tenía dudas durante las prácticas.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '55ad8bf20ca4e10fd9a03673fe0526417c2c16a22cdd1eb5fafada17ad3c29a4'::TEXT, ARRAY[1355]::BIGINT[]),
    (399::BIGINT, 'Sabe mucho del tema, pero las clases teóricas son aburridas y no ayuda si algo sale mal en el laboratorio por culpa de los materiales. La idea de proyecto está mal planteada y no corresponde a un curso de un crédito.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2019-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'da3ccdd2c7956b6407874603ca5bb269aa98f5e4108d39019ececf55b849692e'::TEXT, ARRAY[1355]::BIGINT[]),
    (399::BIGINT, 'No ayuda nunca, si le pregunta se le caga, además califica duro y perjudica por cualquier cosa... Sin embargo, es uno de los profes más brillantes en cuanto a conocimiento que he tenido... El curso se pasa pero se sufre.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-10T00:00:00+00:00'::TIMESTAMPTZ, '344e6ae4438ee58ddec2c41952b31ec9acc20f53f59d1c9ca2991dbc31fcb635'::TEXT, ARRAY[1299]::BIGINT[]),
    (399::BIGINT, 'Es buen profesor, sus clases no son muy entretenidas pero utiliza presentaciones y suelen estar en el TEC Sigital. El único inconveniente es la evaluación, ya que son exámenes que si bien son de marque con x, sólo poseen 20 preguntas; son dos exámenes y cada uno vale 40%. Es muy pasable.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'dcaa1bf5f6994f0c1eea468ddd09755ab7b51fa56217868505795ff8ff626c6f'::TEXT, ARRAY[1274]::BIGINT[]),
    (399::BIGINT, 'Es demasiado malo, no atiende ninguna duda, y si le preguntas algo desaparece'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-24T00:00:00+00:00'::TIMESTAMPTZ, 'ad93131e3b1b30681efd84fdcd84dc5643cfed248210c312bd7cf87264534c83'::TEXT, ARRAY[1300, 1376]::BIGINT[]),
    (399::BIGINT, '¡Un crack para proba! Domina la materia, explica demasiado bien y exámenes sencillos, además no exige demasiada carga académica. Se aprende bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '053252ad7f0c4153c53dfa0ae4824ef87750f498c616890e0e246ca08dd9ad6d'::TEXT, ARRAY[1274]::BIGINT[]),
    (399::BIGINT, 'Desaparece a los cinco minutos. Si algo no funciona, es muy brusco para calificar. No es flexible con las entregas, pero se aprende.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '6af96ff2bb5b2e6cdfb1c6006a24d83bedf342f7164efba45db212a1886c56c2'::TEXT, ARRAY[1376]::BIGINT[]),
    (399::BIGINT, 'Es muy claro y ordenado con sus asignaciones, si se le pide ayuda está siempre disponible. Es pura vida, pero es como si no estuviera en el laboratorio xD.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'f1336defde9b2169f11e73e0e3fcccedf3a305efc8094c47d6047f58a128ca6e'::TEXT, ARRAY[1300]::BIGINT[]),
    (399::BIGINT, 'En clases esta sentado, cuando uno le pregunta en vez de aclarar empieza a calificar, es mas como un supervisor en el lab a veces si explica,uno al final aprende'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'fc2d1e04f53624d8eb3dc45e777a7863a4f2df3d0a497a15aa9792e175a510d6'::TEXT, ARRAY[1300, 1376]::BIGINT[]),
    (399::BIGINT, 'Como es un laboratorio en el que se asignan proyectos, el profe asigna y revisa :) Muy abierto a consultas y es buena nota.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'e9ff714ffc4a908e7c32e42be8134e613a2d17576cb19c553ea289f67f9f88cc'::TEXT, ARRAY[1300, 1376]::BIGINT[]),
    (399::BIGINT, 'En realidad solo esta ahi para calificar. No ayuda mucho pero no califica duro aunque su sistema de evaluacion es algo confuso. Al final hasta él esta harto del semestre que califica el ultimo proyecto suave.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-14T00:00:00+00:00'::TIMESTAMPTZ, '1b38e8f0414821b53ee039c3e14a840231cc72aedfaee2ef1e6174f1069033a1'::TEXT, ARRAY[1300, 1376]::BIGINT[]),
    (399::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-08-06T00:00:00+00:00'::TIMESTAMPTZ, '98b8132a0087abc254d1122f9f83454dc912294ceced610d50d6eb061d0c7e6e'::TEXT, ARRAY[1288]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
